package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.TypedFields.require;
import java.util.*;
import org.apache.commons.codec.digest.DigestUtils;
/** Owned dictionary assessment and exact reviewed native plan creation. */
final class MigrationMappings {
 private MigrationMappings() {}
 static Map<String,Object> destination(Store.Db db,String target)throws Exception{Service.requireAccountAdministrator(db,db.viewerId);var schema=Service.schema(db,target);RecordPolicy.read(db,schema);RecordPolicy.require(schema,"create",db.viewerRole);return schema;}
 static Map<String,Object> directory(Store.Db db)throws Exception{Service.requireAccountAdministrator(db,db.viewerId);var targets=new ArrayList<Map<String,Object>>();for(var row:db.all("SELECT name,definition FROM os_schema ORDER BY name")){var definition=object(row.get("definition"));if(RecordPolicy.allows(definition,"read",db.viewerRole) && RecordPolicy.allows(definition,"create",db.viewerRole))targets.add(map("name",row.get("name"),"label",definition.get("label")));}return map("targets",targets,"assessments",db.all("SELECT assessment_id,source_table,target,created,job_id FROM os_source_assessment WHERE owner_id=? ORDER BY created DESC,assessment_id LIMIT 20",db.viewerId));}
 static Map<String,Object> owned(Store.Db db,String id)throws Exception{Service.requireAccountAdministrator(db,db.viewerId);var row=db.one("SELECT * FROM os_source_assessment WHERE assessment_id=? AND owner_id=?",id,db.viewerId);if(row==null)throw new Failure(404,"Mapping assessment not found");return row;}
 static String proof(Store.Db db,Map<String,Object> row)throws Exception{return DigestUtils.sha256Hex(JSON.writeValueAsString(map("actor",db.viewerId,"authority",db.one("SELECT auth_revision FROM os_user WHERE user_id=?",db.viewerId),"schema",destination(db,row.get("target").toString()))));}
 static Map<String,Object> page(Store.Db db,String id)throws Exception{var row=owned(db,id);var schema=destination(db,row.get("target").toString());var definition=object(row.remove("definition"));row.remove("owner_id");row.putAll(definition);row.put("destination",schema);row.put("current",Objects.toString(definition.get("proof"),"").equals(proof(db,row)));row.remove("proof");return row;}
 static Map<String,Object> assess(Store store,Store.Db db,Object input)throws Exception{
  Service.requireAccountAdministrator(db,db.viewerId);var body=object(input);require(body.keySet().equals(Set.of("source","source_table","target","token")),"Provide source, source_table, target and token");String source=ServiceNowSource.origin(WorkJobs.text(body.get("source"),320),store.migrationOrigins),table=SourceDictionary.name(body.get("source_table")),target=SourceDictionary.name(body.get("target"));require(!TransferJobs.SUPPORT.containsKey(table),"Choose a migratable record table");var schema=destination(db,target);require(db.count("SELECT COUNT(*) FROM os_source_assessment WHERE owner_id=?",db.viewerId)<20 && db.count("SELECT COUNT(*) FROM os_source_assessment")<5000,"Mapping assessment capacity reached");var definition=SourceDictionary.inspect(source,WorkJobs.text(body.get("token"),4096),table);var suggested=map();for(String field:object(schema.get("fields")).keySet()){var candidate=object(object(definition.get("fields")).getOrDefault(field,map("eligible",false)));if(Boolean.TRUE.equals(candidate.get("eligible")))suggested.put(field,field);}definition.put("suggested",suggested);definition.put("review",null);definition.put("proof","");String id=Values.id();db.update("INSERT INTO os_source_assessment(assessment_id,owner_id,source_url,source_table,target,definition,revision,job_id,created) VALUES(?,?,?,?,?,?,1,'',?)",id,db.viewerId,source,table,target,JSON.writeValueAsString(definition),now());SecurityEvents.record(db,db.viewerId,db.viewerId,"migration.mapping_assessed",map("assessment_id",id,"source_table",table,"target",target,"field_count",object(definition.get("fields")).size()));return page(db,id);
 }
 static Map<String,Object> plan(Store.Db db,Map<String,Object> row,Object input)throws Exception{
  var mapping=object(input);require(mapping.keySet().equals(Set.of("fields","values")),"Provide fields and values only");Map<String,Object> fields=object(mapping.get("fields")),translations=object(mapping.get("values")),source=object(object(row.get("definition")).get("fields")),schema=destination(db,row.get("target").toString());require(!fields.isEmpty() && fields.size()<=100 && fields.containsKey("short_description"),"Map a summary and at most100 fields");for(var entry:fields.entrySet()){require(object(schema.get("fields")).containsKey(entry.getKey()),"Choose an existing destination field");String name=WorkJobs.text(entry.getValue(),64);require(Boolean.TRUE.equals(object(source.getOrDefault(name,map("eligible",false))).get("eligible")),"Choose a supported assessed source field");}require(fields.keySet().containsAll(translations.keySet()),"Translate mapped fields only");for(Object values:translations.values()){var choices=object(values);require(choices.size()<=100,"At most100 translations per field");for(var entry:choices.entrySet()){require(entry.getKey().length()<=200,"Source choice exceeds200 characters");WorkJobs.text(entry.getValue(),200);}}return map("source",row.get("source_url"),"tables",map(row.get("source_table").toString(),map("target",row.get("target"),"fields",fields,"values",translations)),"identities",false,"roles",map(),"history",false,"attachments",false);
 }
 static Map<String,Object> command(Store store,Store.Db db,String id,Object input)throws Exception{
  var row=owned(db,id);var body=object(input);String operation=WorkJobs.text(body.get("operation"),12);require(Set.of("review","create").contains(operation),"Choose review or create");boolean create=operation.equals("create");require(body.keySet().equals(create?Set.of("operation","revision","confirm"):Set.of("operation","revision","mapping")),"Provide only the reviewed mapping fields");ProblemInvestigations.revision(body.get("revision"),row.get("revision"));if(create)require(Boolean.TRUE.equals(body.get("confirm")),"Confirm creating this exact migration plan");var definition=object(row.get("definition"));if(!row.get("job_id").equals("")){if(!create)throw new Failure(409,"This assessment already created its migration");return page(db,id);}ServiceNowSource.origin(row.get("source_url").toString(),store.migrationOrigins);if(!create){var plan=plan(db,row,body.get("mapping"));definition.put("review",plan);definition.put("proof",proof(db,row));db.update("UPDATE os_source_assessment SET definition=?,revision=revision+1 WHERE assessment_id=?",JSON.writeValueAsString(definition),id);return page(db,id);}require(definition.get("review") instanceof Map<?,?>,"Review a mapping before creating its migration");if(!definition.get("proof").equals(proof(db,row)))throw new Failure(409,"Destination or authority changed; review the mapping again");var migration=TransferJobs.create(db,definition.get("review"),db.viewerId,store.migrationOrigins);db.update("UPDATE os_source_assessment SET job_id=? WHERE assessment_id=?",migration.get("job_id"),id);SecurityEvents.record(db,db.viewerId,db.viewerId,"migration.mapping_created",map("assessment_id",id,"job_id",migration.get("job_id")));return page(db,id);
 }
}
